Translate("deDE", "wetlands", {
	title = "Sumpfland",
	aliases = { "Das Sumpfland" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Sumpfland ist ein weites Land aus Moor, Schilf und trägem schwarzem Wasser, das nördlich der Berge von Khaz Modan liegt. Nebel hängt einen Großteil des Jahres darüber. Eine große Straße durchquert es: Sie steigt im Süden aus {link:dun-algaz}Dun Algaz{/link} herauf, führt nach Norden an den Ruinen alter Zwergenfesten vorbei und endet am {link:thandol-span}Thandol-Übergang{/link}, der Brücke, die die Lande der {link:dwarves}Zwerge{/link} mit den Menschenkönigreichen des Nordens verbindet. Eine zweite Straße biegt nach Westen zum Meer ab, wo der {link:menethil-harbor}Hafen von Menethil{/link} für die {link:alliance}Allianz{/link} Wache über die Küste hält. Es war schon immer ein hartes Land, reich an Krokilisken und Raptoren und arm an Behaglichkeit. Nun ist es auch ein Land im Krieg.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer als Erster in diesen Sümpfen Stein aufschichtete. Die {link:dwarves}Zwerge{/link} beanspruchen sie seit vielen Jahrhunderten. Im Osten steht die Bergfestung {link:grim-batol}Grim Batol{/link}, einst der Sitz des Wildhammerklans. Im Krieg der drei Hämmer griffen die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} Grim Batol an, und die finstere Zauberei, die dort entfesselt wurde, hinterließ die Festung verderbt. Die Wildhammers gaben sie auf und zogen nach Norden in die Gipfel des {link:the-hinterlands}Hinterlands{/link}. Die {link:explorers-league}Forscherliga{/link} findet unter dem Schlamm noch ältere Dinge: Knochen großer Tiere und Steine, in die eine Schrift gemeißelt ist, die kein Zwerg geschrieben hat.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:menethil-harbor}Der Hafen von Menethil{/link} hält die Westküste für die {link:alliance}Allianz{/link} unter den Zwergen des {link:kingdom-of-ironforge}Königreichs Ironforge{/link}. Jenseits seiner Mauern zerfällt das Sumpfland. Saboteure der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} haben den {link:thandol-span}Thandol-Übergang{/link} zerstört und {link:dun-modr}Dun Modr{/link} eingenommen, und die Überlebenden des Regiments, das beides hielt, warten in den Ruinen auf eine Reserve, die nie eintrifft. Die {link:dragonmaw-clan}Orcs der Dragonmaw{/link}, nach dem {link:second-war}Zweiten Krieg{/link} geschlagen und zerstreut, haben einen neuen Häuptling und ein neues Lager gefunden. Sie sind nach {link:dun-algaz}Dun Algaz{/link} vorgedrungen und drohen, Menethil von {link:loch-modan}Loch Modan{/link} abzuschneiden. An {link:whelgar-s-excavation-site}Whelgars Ausgrabungsstätte{/link} haben Raptoren den Großteil einer Grabung der {link:explorers-league}Forscherliga{/link} getötet. Über dieser Grabung hat Nebel begonnen, aus den Bergen herabzutreiben, Lichter flackern auf den Höhen, und Konstrukte aus Stein wandeln dort, wo seit Zeitaltern niemand gewandelt ist. Die einzige hoffnungsvolle Nachricht kommt über das Meer: Neue Schiffe segeln nun von Menethil nach {link:southshore}Southshore{/link} und weiter nach {link:auberdine}Auberdine{/link}.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}.{/b} Soldaten, Bergleute, Priester und Gelehrte halten den Hafen von Menethil, das Lager vor {link:dun-modr}Dun Modr{/link} und die Grabung der {link:explorers-league}Forscherliga{/link}.
• {b}Die Leute von Menethil.{/b} {link:humans}Menschen{/link} der alten Königreiche arbeiten neben den Zwergen in seinen Docks, Tavernen und Gerbereien.
• {b}Der {link:dragonmaw-clan}Dragonmawklan{/link}.{/b} {link:orcs}Orcs{/link}, die einst auf roten Drachen in den Krieg ritten, lagern nun in den Hügeln östlich der Straße.
• {b}Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}.{/b} Ihre Saboteure, Tunnelgräber und Hexenmeister halten Dun Modr und {link:direforge-hill}Direforge Hill{/link}.
• {b}Die Moosfell-Gnolle.{/b} Ein Klan von {link:gnolls}Gnollen{/link} der Moore, zu zahlreich geworden für das Land, das sie ernährt.
• {b}Die Blaukiemen-Murlocs.{/b} {link:murlocs}Murlocs{/link}, die die Küste und die Handelsschiffe überfallen, die an ihr vorbeiziehen.
• {b}Die ertrunkenen Toten.{/b} Verfluchte Seeleute wandeln noch auf den Wracks der Verlorenen Flotte an der Nordwestküste.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die drei Hämmer.{/b} {link:grim-batol}Grim Batol{/link} verstummte nach dem Krieg der drei Klans, und die Wildhammers ließen das Sumpfland hinter sich.
• {b}Der Zweite Krieg.{/b} Die {link:horde}Horde{/link} überrannte Khaz Modan. Der {link:dragonmaw-clan}Dragonmawklan{/link} machte Grim Batol zu seiner Festung, und die {link:orcs}Orcs{/link} bauten an der Westküste einen Hafen, um {link:hillsbrad-foothills}Hillsbrad{/link} vom Meer aus anzugreifen. Rote Drachen unter dem Befehl der Orcs verbrannten die {link:third-fleet}Dritte Flotte{/link} von {link:kul-tiras}Kul Tiras{/link} vor diesen Küsten.
• {b}Menethil.{/b} Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} vertrieb die Orcs aus ihrem Hafen, und die {link:alliance}Allianz{/link} errichtete auf demselben Grund einen eigenen Hafen, benannt nach König {link:terenas-menethil}Terenas Menethil{/link}.
• {b}Die Gegenwart.{/b} Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} erhoben sich im Norden, die Dragonmaw kehrten im Osten zurück, und die Reserven von {link:ironforge}Ironforge{/link} wurden an andere Fronten geschickt.]=],
		},
		{
			title = "Überlieferungen des Sumpflands",
			text = [=[• Die Krokiliskenhäute der Gerberei von Menethil werden in Häfen in aller Welt verkauft.
• Ein Geist des Sumpfes, den man den Grünwächter nennt, wandelt zwischen den Krokilisken östlich der Abzweigung nach {link:dun-modr}Dun Modr{/link}. Jenen, die ihn suchen, wird gesagt, dass sie nicht zurückkehren werden.
• Die Moosfell-{link:gnolls}Gnolle{/link} verbrennen lebende Bäume, um sich zu wärmen, und der Grünwächter hat ihnen nicht vergeben.
• Der letzte Überlebende der Dritten Flotte sagt, dass er in seinen Träumen noch das Stöhnen seiner ertrunkenen Brüder hört.]=],
		},
	},
})

Translate("deDE", "menethil-harbor", {
	title = "Der Hafen von Menethil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Hafen von Menethil ist der Hafen der {link:alliance}Allianz{/link} an der Westküste des Sumpflands. Er steht auf dem Grund, auf dem die {link:horde}Horde{/link} einst Schiffe für den Zweiten Krieg baute, und viel von dem Holz und Eisen, das sie aus Khaz Modan stahl, liegt noch um seine Docks herum. Seine Burg trägt den Namen von König {link:terenas-menethil}Terenas Menethil{/link}. Die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link} befehligen ihn, und {link:captain-stoutfist}Hauptmann Stoutfist{/link} plant seine Verteidigung im Kriegsraum der Burg Menethil. Schiffe segeln von seinen Piers nach {link:auberdine}Auberdine{/link}, nach {link:theramore-isle}Theramore{/link} jenseits des Meeres und nun auch nach {link:southshore}Southshore{/link}. In der Deepwater Taverne teilen sich Seeleute, Gelehrte, Spione und ein betrunkener Überlebender der Dritten Flotte dieselben Tische.]=],
		},
	},
})

Translate("deDE", "dun-modr", {
	title = "Dun Modr",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dun Modr ist eine Zwergenstadt im Norden des Sumpflands, an der Straße zum {link:thandol-span}Thandol-Übergang{/link}. Ein Regiment aus {link:ironforge}Ironforge{/link} hielt sie und die Brücke dahinter. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} schlugen zuerst gegen die Brücke zu und fielen dann über die Stadt her, bevor sich das Regiment sammeln konnte, und die meisten {link:dwarves}Zwerge{/link} wurden getötet. {link:longbraid-the-grim}Longbraid der Grimmige{/link} blies zum Rückzug. Was von seinem Regiment übrig ist, lagert nun gleich vor den Mauern, während Soldaten, Tunnelgräber und Sprengmeister der Dunkeleisenzwerge die Straßen halten. Man hat unter ihnen eine angekettete Kreatur des Feuers gesehen, und ein Elementar namens Modr wandelt durch die Ruinen.]=],
		},
	},
})

Translate("deDE", "thandol-span", {
	title = "Thandol-Übergang",
	aliases = { "Der Thandol-Übergang" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Thandol-Übergang ist die große Brücke am Nordrand des Sumpflands. Sie überspannt eine tiefe Schlucht zum {link:arathi-highlands}Arathihochland{/link} und trägt die Hauptstraße zwischen Khaz Modan und den nördlichen Landen. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} sprengten in einem Hinterhalt ihre westliche Brücke, und viele {link:dwarves}Zwerge{/link} starben mit ihr, unter ihnen der Bruder von {link:longbraid-the-grim}Longbraid{/link} dem Grimmigen. Den Plan hatte ein Dunkeleisenzwerg namens {link:kam-deepfury}Kam Deepfury{/link} ersonnen. Seine Agenten versteckten jenseits der Schlucht weiteren Sprengstoff, um den Rest zum Einsturz zu bringen. Fällt der Übergang, verlieren die Zwerge ihren wichtigsten Versorgungsweg nach Norden.]=],
		},
	},
})

Translate("deDE", "whelgar-s-excavation-site", {
	title = "Whelgars Ausgrabungsstätte",
	aliases = { "Whelgars Ausgrabung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Whelgars Ausgrabungsstätte ist eine Grabung der {link:explorers-league}Forscherliga{/link} inmitten des Sumpflands. Die Mannschaft von {link:prospector-whelgar}Prospektor Whelgar{/link} legte uralte Relikte frei, als sie auf gewaltige Knochen zu stoßen begann. Bald darauf fielen die gefleckten Raptoren des Sumpfes über die Stätte her. Viele Gräber starben. Drei Überlebende harren auf einer Anhöhe über den Ruinen ihres Lagers aus. Unter den Funden ist eine zerbrochene Tafel, in die Schrift der Titanen gemeißelt, der {link:goaz-stone}Goaz-Stein{/link}. Höher in den Hügeln im Südosten, jenseits der alten Grabung, liegt ein zweites Lager, das die Liga eröffnet hat, und von dort führt ein Weg in die {link:excavation-site}Ausgrabungsstätte{/link}.]=],
		},
	},
})

Translate("deDE", "dun-algaz", {
	title = "Dun Algaz",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dun Algaz ist der Gebirgspass zwischen {link:loch-modan}Loch Modan{/link} und dem {link:wetlands}Sumpfland{/link}, an seinem südlichen Ausgang von den Zwergen der {link:algaz-station}Station Algaz{/link} bewacht. Er ist die einzige Straße, auf der die Soldaten von {link:ironforge}Ironforge{/link} den Hafen von Menethil über Land erreichen können. Die {link:dragonmaw-clan}Orcs der Dragonmaw{/link} hielten sich stets in den Hügeln, doch nun sind sie in großer Zahl in den Pass herabgekommen, angeführt von einem Kriegsherrn namens {link:ma-ruk-wyrmscale}Ma'ruk Wyrmscale{/link}. Niemand in Menethil kann sagen, was sie dazu trieb. Halten sie Dun Algaz, steht der Hafen allein.]=],
		},
	},
})

Translate("deDE", "grim-batol", {
	title = "Grim Batol",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grim Batol ist eine Bergfestung im äußersten Osten des Sumpflands, hinter den Toren der {link:dragonmaw-clan}Dragonmaw{/link}. Sie wurde von den Zwergen der Wildhammer erbaut, und sie verließen sie nach dem Krieg der drei Hämmer, als finstere Zauberei ihre Hallen besudelte. Im {link:second-war}Zweiten Krieg{/link} machte der Dragonmawklan sie zu seiner Festung. Dort hielt er {link:alexstrasza}Alexstrasza{/link}, die Königin der roten Drachen, in Ketten, durch die Macht eines Artefakts, das {link:deathwing}Todesschwinge{/link} geschaffen hatte, und zog ihre Jungen als Kriegsreittiere auf. Die Königin ist seither befreit. Rote Drachen sammeln sich nun vor den Toren von Grim Batol, und sie dulden keine Fremden.]=],
		},
	},
})

Translate("deDE", "angerfang-encampment", {
	title = "Angerfang-Lager",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Angerfang-Lager ist das Kriegslager der {link:dragonmaw-clan}Orcs der Dragonmaw{/link}, in den Hügeln östlich der Straße durch das {link:wetlands}Sumpfland{/link}. Nach dem Zweiten Krieg flohen die wenigen Dragonmaw, die die Rache der roten Drachen überlebten, aus {link:grim-batol}Grim Batol{/link} und versteckten sich in diesen Bergen. Hier sind sie unter {link:chieftain-nek-rosh}Häuptling Nek'rosh{/link} wieder stark geworden. Ihre Kriegsbanner wehen über dem Lager, ihre Zenturionen und Schattenwächter exerzieren darin, und ihre Belagerungskatapulte stehen bereit für den Marsch auf den Hafen von Menethil.]=],
		},
	},
})

Translate("deDE", "dragonmaw-retreat", {
	title = "Dragonmaw Retreat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dragonmaw Retreat ist ein verborgener Stützpunkt der {link:dragonmaw-clan}Orcs der Dragonmaw{/link} in den östlichen Hügeln des Sumpflands. Hier lagert der Klan Waffen für Soldaten, die er noch nicht bewaffnet hat. Seine Krieger sind nicht nur Kämpfer: Seelenbinder und Rückeroberer gehen unter ihnen umher, und man hat dort eine Drachenbrut gesehen, gebeugt und unterworfen. {link:captain-stoutfist}Hauptmann Stoutfist{/link} würde den Vorrat gern fortgeschafft sehen, bevor er benutzt werden kann. Was die {link:orcs}Orcs{/link} zurückzuerobern gedenken, können die {link:dwarves}Zwerge{/link} nur erraten.]=],
		},
	},
})

Translate("deDE", "mosshide-fen", {
	title = "Moosfellmoor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Moosfellmoor ist ein Stück Sumpf im Süden des Sumpflands, nahe dem Zwergentor von Algaz. Es hat seinen Namen von den Moosfell-Gnollen. Die {link:gnolls}Gnolle{/link} haben viele Jahre still in den Mooren gelebt, doch ihre Zahl ist gewachsen. Sie zertrampeln die Sträucher und Blumen des Sumpfes und fällen seine Bäume für ihre Feuer, und sie tragen grobe Feuersteine bei sich, um sie zu entzünden. Der Geist, den man den Grünwächter nennt, hat sie als eine Wunde im Land gezeichnet.]=],
		},
	},
})

Translate("deDE", "sundown-marsh", {
	title = "Sonnenwendmarschen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Sonnenwendmarschen liegen im Norden des Sumpflands, ein nasses, tiefes Land aus Tümpeln und Schilf. Auch hier jagen Moosfell-{link:gnolls}Gnolle{/link}, unter ihnen ihre Mystiker und Alphatiere. Seltsamere Dinge steigen aus dem Wasser. Moorkriecher schlurfen durch die Kanäle, und größere Moorfürsten stehen zwischen ihnen. {link:rethiel-the-greenwarden}Der Grünwächter{/link} nennt sie fiebrige Blasen auf dem Land, geboren aus einer Fäulnis, die niemand erklären kann, und er würde sie in den Sumpf zurückgelegt sehen.]=],
		},
	},
})

Translate("deDE", "saltspray-glen", {
	title = "Salzgischtschlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Salzgischtschlucht ist eine Senke im nordwestlichen {link:wetlands}Sumpfland{/link}, offen für den Wind vom Meer. Es ist Raptorenland. Die Klingenmaulraptoren, die hier jagen, sind nach ihren Zähnen benannt, lang und scharf genug, um die Schuppen eines Drachenwelpen zu durchbohren, und ihre Eier sollen Dotter so groß wie ein Gnomkopf enthalten. Der {link:dwarves}Zwerg{/link} {link:howin-kindfeather}Howin Kindfeather{/link} schickt Jäger nach beidem hierher.]=],
		},
	},
})

Translate("deDE", "ironbeard-s-tomb", {
	title = "Ironbeards Grabmal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ironbeards Grabmal ist eine alte Grabstätte der {link:dwarves}Zwerge{/link} im Norden des Sumpflands, nicht weit von {link:dun-modr}Dun Modr{/link}. Wer auch immer Ironbeard war, das {link:the-sepulcher}Grabmal{/link} hat seinen Namen überdauert. Tropfende purpurne Schlicke kriechen nun hindurch und verschlingen, was sie berühren. Eine Frau aus Menethil namens {link:sida}Sida{/link} macht sich noch immer einmal in der Woche hierher auf, Schlicke hin oder her, und musste einmal ohne ihre Tasche vor ihnen fliehen.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik erzählt, wer Ironbeard war, wann er hier zur Ruhe gebettet wurde oder warum {link:sida}Sida{/link} sein Grab besucht.]=],
		},
	},
})

Translate("deDE", "direforge-hill", {
	title = "Direforge Hill",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Direforge Hill erhebt sich östlich von {link:dun-modr}Dun Modr{/link}. Er ist das Hauptlager der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} im {link:wetlands}Sumpfland{/link}. Von hier aus graben ihre Tunnelgräber, brechen ihre Saboteure auf und tragen ihre Sprengmeister das Pulver, das den {link:thandol-span}Thandol-Übergang{/link} zerbrach. Ihr Herr in diesen Landen ist der Hexenmeister {link:balgaras-the-foul}Balgaras der Faulige{/link}, der selten in den Kämpfen zu sehen ist. Die {link:dwarves}Zwerge{/link} in Longbraids Lager wissen, dass der Krieg um den Norden auf diesem Hügel entschieden wird.]=],
		},
	},
})

Translate("deDE", "raptor-ridge", {
	title = "Raptorgrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Raptorgrat ist ein hoher, felsiger Absatz im Nordosten des Sumpflands. Er ist die Heimat der Klingenmaulraptoren, und eine große Matriarchin ihrer Art herrscht über den Grat. Nur wenige Jäger steigen freiwillig hinauf. Wer es tut, kommt wegen der Zähne und Eier der Klingenmäuler, und kehrt mit Narben zurück.]=],
		},
	},
})

Translate("deDE", "bluegill-marsh", {
	title = "Blaukiemenmarschen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Blaukiemenmarschen liegen an der Küste nördlich des Hafens von Menethil. Die Blaukiemen-{link:murlocs}Murlocs{/link} sind aus dem tiefen Wasser heraufgekrochen und haben ihre Hütten an ihrem Ufer gebaut. Sie machen Jagd auf Fischer und Händler auf der Straße, und als das Handelsschiff {i}Blind Princess{/i} vorüberfuhr, zerrten sie einen Großteil seiner Ladung über Bord. Ein Murloc namens Gobbler führt Überfälle von der Flussmündung aus und schlüpft stets in die Sicherheit der Hütten zurück.]=],
		},
	},
})

Translate("deDE", "black-channel-marsh", {
	title = "Schwarzkanalmarschen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Schwarzkanalmarschen sind ein Labyrinth aus dunklem Wasser und Schilf im Westen des Sumpflands, zwischen dem Hafen von Menethil und der Grabung der {link:explorers-league}Forscherliga{/link}. Ihre Kanäle sind das Revier der riesigen Krokilisken, die die Gerber von Menethil so schätzen, und die gefleckten Raptoren der Hügel kommen an ihre Ränder herab, um zu jagen. Der Lehrling des Gerbers ging hierher, um Krokilisken zu häuten, und die Krokilisken nahmen ihm sein Bein.]=],
		},
	},
})

Translate("deDE", "the-green-belt", {
	title = "Der grüne Gürtel",
	aliases = { "Grüner Gürtel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der grüne Gürtel ist ein langes Tal aus Gras und Wasser im Osten des Sumpflands, östlich der Straße, wo sie nach {link:dun-modr}Dun Modr{/link} abzweigt. Purpurne Drachenwelpen nisten an ihm entlang. Bären, von einer Krankheit rasend geworden, streifen über seine Hänge. {link:rethiel-the-greenwarden}Der Grünwächter{/link}, der Geist des Sumpfes, wandelt hier zwischen den Krokilisken, und die {link:orcs}Orcs{/link} der Hügel sind nie weit entfernt.]=],
		},
	},
})

Translate("deDE", "the-lost-fleet", {
	title = "Die verlorene Flotte",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die verlorene Flotte ist der Schiffsfriedhof an der Nordwestküste des Sumpflands. Hier brannte und sank die {link:third-fleet}Dritte Flotte{/link} von {link:kul-tiras}Kul Tiras{/link} im Zweiten Krieg unter dem Feuer roter Drachen. Ihre Rümpfe liegen noch in den Untiefen. Nicht alle Mannschaften fanden Ruhe. Etwas Verfluchtes wurde an Bord eines der Schiffe versteckt, und seine Macht hält die ertrunkenen Seeleute und Marinesoldaten auf ihren verrottenden Decks fest, ihren Kapitän unter ihnen.]=],
		},
	},
})

Translate("deDE", "thelgen-rock", {
	title = "Thelgenfelsen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Thelgenfelsen ist eine Höhle in den Hügeln des südlichen Sumpflands, südöstlich von Whelgars Grabung. Spinnen füllen sie, und ihr Gift ist so stark, dass die Alchemisten von Menethil ihre unversehrten Drüsen brauchen, um Gegengift herzustellen. Eine große Spinne namens Blutegelwitwe jagt nahe ihrem Eingang. Der Pfad am Thelgenfelsen vorbei steigt ins Hochland hinauf, wo die {link:excavation-site}Ausgrabungsstätte{/link} liegt.]=],
		},
	},
})

Translate("deDE", "the-drunken-dwarf", {
	title = "The Drunken Dwarf",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[The Drunken Dwarf ist eine Taverne, die vor Kurzem im Süden des Sumpflands eröffnet hat, nahe der Straße aus {link:dun-algaz}Dun Algaz{/link}. Sie ist ein willkommener Anblick für Reisende, die mit {link:orcs}Orcs{/link} auf den Fersen durch den Pass gekommen sind. Aurian Highgrove führt die Theke. Die Firebrews, Bhalir und Agriel, führen die Küche. Ihr Name, der betrunkene {link:dwarves}Zwerg{/link}, ist ein Versprechen, das die meisten ihrer Gäste gern einlösen.]=],
		},
	},
})

Translate("deDE", "captain-stoutfist", {
	title = "Hauptmann Stoutfist",
	subtitle = "Befehlshaber der Burg Menethil",
	found = "Der Kriegsraum der Burg Menethil",
	hint = [=[Sucht den Hauptmann auf, der im Kriegsraum ihrer Burg die Verteidigung von Menethil plant.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Stoutfist" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Stoutfist befehligt den Hafen von Menethil für das {link:kingdom-of-ironforge}Königreich Ironforge{/link}. Vom Kriegsraum der Burg Menethil aus behält er drei Feinde zugleich im Auge: die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} im Norden, die {link:dragonmaw-clan}Dragonmaw{/link} in den Hügeln und die {link:orcs}Orcs{/link}, die nun den Pass von {link:dun-algaz}Dun Algaz{/link} abschnüren. Er hat wenige Soldaten und noch weniger Verstärkung. Er ruft jeden Kämpfer zu sich, der aus dem Pass kommt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stoutfist ist der Mann, von dem die ganze Westküste abhängt. Fällt Menethil, verliert die {link:alliance}Allianz{/link} ihren Hafen im Norden und die Straße zwischen {link:ironforge}Ironforge{/link} und dem Meer.]=],
		},
		{
			title = "Taten",
			text = [=[• Er empfängt die Berichte von {link:valstag-ironjaw}Valstag Ironjaw{/link} über den Vorstoß der {link:dragonmaw-clan}Dragonmaw{/link} nach {link:dun-algaz}Dun Algaz{/link}.
• Er schickt Kämpfer gegen das {link:angerfang-encampment}Angerfang-Lager{/link}, um die Kriegsbanner der {link:orcs}Orcs{/link} zu erbeuten.
• Er befiehlt, die Katapulte der Dragonmaw zu verbrennen und ihren Häuptling zu töten.
• Er will die Waffen von {link:dragonmaw-retreat}Dragonmaw Retreat{/link} fortgeschafft sehen, bevor sie neue Soldaten bewaffnen können.]=],
		},
	},
	chapters = {
		{
			title = "Nek'roshs Gambit",
			hint = [=[Findet heraus, was die Dragonmaw in ihrem Lager gebaut haben.]=],
			text = [=[Die Kämpfer, die Angerfang überfielen, kamen mit mehr als Bannern zurück. Sie hatten Katapulte gesehen. {link:chieftain-nek-rosh}Nek'rosh{/link} wollte Menethil belagern, und mit {link:dun-algaz}Dun Algaz{/link} in der Hand der {link:orcs}Orcs{/link} konnte keine Hilfe den Hafen rechtzeitig erreichen. Stoutfist verteilte Zunder und gab einen einfachen Befehl: Verbrennt die Maschinen, dann schlagt dem Untier den Kopf ab.]=],
		},
		{
			title = "Die Statuette des Königs",
			hint = "Bringt die zurückgewonnene Statuette zur Burg von Menethil.",
			text = [=[Die silberne Statuette, die den {link:murlocs}Murlocs{/link} abgenommen wurde, war für seine Burg bestimmt. Stoutfist war stolz, ein Andenken an {link:terenas-menethil}König Terenas{/link} zu halten, dessen Namen seine Burg trägt, doch er wusste, was sein Hafen war: ein ruhiger Ort inmitten eines Sturms von Feinden. Er fürchtete, was die {link:dragonmaw-clan}Dragonmaw{/link} mit einem solchen Gegenstand tun würden, und schickte ihn zur sicheren Verwahrung nach {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "Meldet Euch bei Hauptmann Stoutfist" },
		{ text = "Kriegsbanner" },
		{ text = "Nek'roshs Gambit" },
		{ text = "Besiegt {link:chieftain-nek-rosh}Nek'rosh{/link}" },
		{ text = "Bringt die Statuette zurück" },
		{ text = "Ein Freund der Familie, an den Hochlord" },
		{ text = "Ein Freund der Familie, an die Kathedrale" },
		{ text = "Erzwungene Entwaffnung" },
	},
	bonds = {
		{ id = "valstag-ironjaw", name = "Valstag Ironjaw", note = "bringt ihm Berichte aus Dun Algaz" },
		{ id = "chieftain-nek-rosh", name = "Häuptling Nek'rosh", note = "Feind" },
		{ id = "karl-boran", name = "Karl Boran", note = "schickte ihm die Statuette" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "der Hochlord, dem er sie anvertraut" },
	},
})

