Translate("deDE", "first-mate-fitzsimmons", {
	title = "Erster Maat Fitzsimmons",
	subtitle = "Letzter Überlebender der Dritten Flotte",
	found = "Die Deepwater Taverne, Hafen von Menethil",
	hint = [=[Spendiert dem Seemann, der in der Deepwater Taverne seine Erinnerungen ertränkt, einen Trunk.]=],
	allegiance = "Kul Tiras (einst)",
	aliases = { "Fitzsimmons" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fitzsimmons war Erster Maat der {i}Wave Mistress{/i}, eines Linienschiffs der {link:third-fleet}Dritten Flotte{/link} von {link:kul-tiras}Kul Tiras{/link}. Auf der letzten Fahrt der Flotte fielen rote Drachen, von {link:orcs}Orcs{/link} geritten, über sie her und verbrannten sie vor der Küste des Sumpflands. Er allein überlebte. Nun verbringt er seine Tage in der Deepwater Taverne, säuerlich riechend und durstig, und seine Nächte träumend von seinen ertrunkenen Brüdern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fitzsimmons ist das lebende Gedächtnis der Verdammten Flotte. Nur er weiß, dass an Bord eines ihrer Schiffe etwas Schreckliches versteckt war und dass dessen Macht die Toten nicht ruhen lässt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erzählt die Geschichte der Dritten Flotte jedem, der ihm Met spendiert.
• Er bittet darum, dass seine verfluchten Brüder befreit werden.
• Er schickt Suchende zum Geist von {link:captain-halyndor}Kapitän Halyndor{/link}, um den Schlüssel zur Schiffstruhe zu holen.
• Er weist den Weg zum Grünwächter und warnt den Suchenden davor, zu gehen.]=],
		},
	},
	chapters = {
		{
			title = "Die Verdammte Flotte",
			hint = "Löst dem alten Seemann mit einem Krug Met die Zunge.",
			text = [=[Mit einem frischen Trunk in der Hand erzählt Fitzsimmons es ohne Umschweife. Die Flotte segelte; die Drachen kamen; die Schiffe brannten und gingen unter. Er weiß nicht, warum er überlebte. Er verflucht seinen Kapitän dafür, sie in ihr Verderben geführt zu haben, und er trinkt auf seine Brüder in ihren nassen Gräbern.]=],
		},
		{
			title = "Das verfluchte Auge",
			hint = "Öffnet die Schiffstruhe der Intrepid.",
			text = [=[{link:captain-halyndor}Kapitän Halyndor{/link} hatte das Ding in seiner Schiffstruhe an Bord der {i}Intrepid{/i} verschlossen gehalten. Als die Truhe geöffnet wurde, enthielt sie eine geschwärzte Kugel, die in einem kränklichen Licht pulsierte: ein Auge von Paleth, besudelt vom Kummer, den es mitangesehen hatte. Fitzsimmons wollte es nicht anfassen. Er schickte es dem Priester {link:glorin-steelbrow}Glorin Steelbrow{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:third-fleet}Die Dritte Flotte{/link}" },
		{ text = "Die verfluchte Mannschaft" },
		{ text = "Den Fluch aufheben" },
		{ text = "{link:rethiel-the-greenwarden}Der Grünwächter{/link}" },
	},
	bonds = {
		{ id = "captain-halyndor", name = "Kapitän Halyndor", note = "sein alter Kapitän, dem er die Schuld gibt" },
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "empfing das Auge" },
		{ id = "rethiel-the-greenwarden", name = "Rethiel der Grünwächter", note = "der Geist, vor dem er warnt" },
	},
})

Translate("deDE", "glorin-steelbrow", {
	title = "Glorin Steelbrow",
	subtitle = "Priester von Menethil",
	found = "Die Deepwater Taverne, Hafen von Menethil",
	hint = [=[Findet den zwergischen Priester, der die Geheimnisse der versunkenen Flotte kennt.]=],
