	aliases = { "Glorin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Glorin Steelbrow ist ein zwergischer Priester des {link:holy-light}Heiligen Lichts{/link}, der im Hafen von Menethil lebt. Er kennt die Wracks der Dritten Flotte besser als die meisten. Ein Schiff, das mit ihr segelte, die {i}Flying Osprey{/i}, trug eine Ladung lichtgeschmiedeten Eisens, eines Metalls, das mit heiliger Kraft zuschlägt. Glorin kann sagen, wo es liegt und wer es bearbeiten kann. Doch als das verfluchte Auge von Paleth in seine Hände kam, konnte er es nicht reinigen. Die Augen wurden von menschlichen Priestern geschaffen, und nur ein menschlicher Meister konnte eines heilen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Suchende zum Wrack der {i}Flying Osprey{/i}, um lichtgeschmiedetes Eisen zu holen.
• Er schickt das verfluchte Auge von Paleth an {link:archbishop-benedictus}Erzbischof Benedictus{/link} in {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "Die Verdammte Flotte" },
		{ text = "Lichtgeschmiedetes Eisen" },
		{ text = "Die verlorenen Barren" },
		{ text = "Gesegneter Arm" },
		{ text = "Das Auge von Paleth" },
		{ text = "Die Reinigung des Auges" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Erster Maat Fitzsimmons", note = "ein Trinker, dem er keine Runde ausgibt" },
		{ id = "archbishop-benedictus", name = "Erzbischof Benedictus", note = "kann das Auge reinigen" },
	},
})

Translate("deDE", "innkeeper-helbrek", {
