})

Translate("deDE", "tapoke-slim-jahn", {
	title = "Tapoke „Slim“ Jahn",
	subtitle = "Ein Verräter in der Taverne",
	found = "Die Deepwater Taverne, Hafen von Menethil",
	hint = [=[Behaltet den Gast im Auge, der in der Deepwater Taverne zu genau zuhört.]=],
	allegiance = "Bruderschaft der Defias (für Bezahlung)",
	aliases = { "Slim", "Tapoke Jahn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tapoke Jahn, den die Unterwelt Slim nennt, trinkt in der Deepwater Taverne und hält die Ohren offen. Er wurde von der {link:defias-brotherhood}Bruderschaft der Defias{/link} für eine einzige Aufgabe im Hafen von Menethil bezahlt, und er erledigte sie. Als er erfuhr, dass Fremde nach ihm fragten, versuchte er, zur Tür hinauszuschlüpfen.]=],
		},
	},
	chapters = {
		{
			title = "Was Slim wusste",
			hint = "Haltet Slim auf, bevor er aus der Taverne entkommt.",
			text = [=[Slim wurde nicht genug bezahlt, um für die {link:defias-brotherhood}Defias{/link} zu sterben, und er sagte es. Der Gefangene, den sie genommen hatten, war kein Diplomat. Es war der König von {link:stormwind-city}Stormwind{/link}, der heimlich nach {link:theramore-isle}Theramore{/link} segelte. Slims Aufgabe war es gewesen, einen einzigen Mann namens {link:private-hendel}Hendel{/link} an Bord des königlichen Schiffes im Hafen zu bringen. Er glaubte, dass die Defias für jemanden arbeiteten, der größer war als sie selbst.]=],
		},
	},
	mentions = {
		{ text = "Der vermisste Diplomat" },
		{ text = "Der vermisste Diplomat" },
	},
	bonds = {
		{ id = "mikhail", name = "Mikhail", note = "entlarvte ihn" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "der König, an dessen Verrat er mitwirkte" },
	},
})

Translate("deDE", "sida", {
	title = "Sida",
	subtitle = "Eine Frau aus Menethil",
