	allegiance = "Hafen von Menethil",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sida lebt im Hafen von Menethil. Einmal in der Woche geht sie den ganzen Weg bis zu {link:ironbeard-s-tomb}Ironbeards Grabmal{/link} nahe {link:dun-modr}Dun Modr{/link}, durch ein Land im Krieg. Bei ihrem letzten Besuch kamen die Schlicke des Grabmals über sie. In ihrer Panik warf sie ihre Tasche nach einem von ihnen, und der Schlick verschlang sie ganz. Sie entkam, doch in der Tasche war etwas, das sie dringend brauchte.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Sida sagt nicht, warum sie das {link:the-sepulcher}Grabmal{/link} besucht oder was sie in ihrer Tasche aufbewahrte. Der Gerber {link:james-halloran}James Halloran{/link} dachte einmal daran, seine Frau zu ihr zu schicken, um mit ihr zu sprechen, sagte aber nicht, warum.]=],
		},
	},
	mentions = {
		{ text = "Wühlen im Schlick" },
		{ text = "Tägliche Lieferung" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "ein Nachbar, der von ihr spricht" },
	},
})

