})

Translate("deDE", "sylessa-duskwhisper", {
	title = "Sylessa Duskwhisper",
	subtitle = "Sucherin der Blüte",
	found = "Hafen von Menethil",
	hint = [=[Sprecht mit der Nachtelfe, die das Meer nach Menethil überquerte, auf der Suche nach einer Blume.]=],
	allegiance = "Nachtelfen von Teldrassil",
	sections = {
		{
			title = "Zusammenfassung",
