Translate("deDE", "prospector-whelgar", {
	title = "Prospektor Whelgar",
	subtitle = "Leiter der Ausgrabung im Sumpfland",
	found = "Die Anhöhe über Whelgars Ausgrabungsstätte",
	hint = [=[Sucht den alten Prospektor, der die Grabung der Forscherliga im Sumpfland leitet.]=],
	allegiance = "Forscherliga",
	aliases = { "Whelgar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektor Whelgar leitet die Grabung der {link:explorers-league}Forscherliga{/link}, die seinen Namen trägt. Er ist alt, zu alt, wie er sagt, um zwischen die Tiere hinabzusteigen, die sein Lager eingenommen haben. Doch sein Verstand ist scharf. Kurz bevor die Raptoren kamen, grub er eine große Tafel aus, den {link:goaz-stone}Goaz-Stein{/link}, gemeißelt in der Schrift der Titanen und an vier Stellen zerbrochen. Er glaubt, dass die fehlenden Stücke den Schlüssel zu einem Rätsel bergen, das größer ist als jedes, das die Liga bisher gefunden hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Whelgars Tafel spricht von einem göttlichen Plan und einer unheilvollen Prophezeiung, und von Alten Göttern, die unter dem Land angekettet sind. Wenige Funde der Liga haben an ältere oder finsterere Dinge gerührt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er besitzt das ursprüngliche Fossil, das {link:archaeologist-flagongut}Archäologe Flagongut{/link} erforschen möchte.
• Er überlebte den Raptorenangriff auf seine Grabung mit {link:merrin-rockweaver}Merrin Rockweaver{/link} und {link:ormer-ironbraid}Ormer Ironbraid{/link}.
• Er arbeitet daran, die Titanenschrift des Goaz-Steins zu übersetzen.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Keine Chronik verzeichnet Whelgars Leben vor der Grabung oder wie lange er der Liga schon dient.]=],
		},
	},
	chapters = {
		{
			title = "Der Goaz-Stein",
			hint = [=[Holt die fehlenden Bruchstücke der Tafel des Prospektors zurück.]=],
			text = [=[Die Bruchstücke trugen die Namen Ados, Modr, Golm und Neru, und sie lagen verstreut in den Trümmern der Grabung, zwischen alten Relikten und loser Erde. Als das letzte eingefügt war, beugte sich Whelgar über den Stein und begann zu lesen. Sofort kamen ihm neue Worte, und er sprach sie laut aus: Alte Götter, angekettet unter dem Land. Er sagte nicht, was sie seiner Befürchtung nach bedeuteten. Er sagte nur, es sei der Anfang von etwas Großem.]=],
		},
	},
	mentions = {
		{ text = "Die Vergangenheit enthüllen" },
		{ text = "Der zerstreute Prospektor" },
		{ text = "Auf der Suche nach der Ausgrabungsmannschaft" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "eine Gräberin seiner Mannschaft" },
		{ id = "ormer-ironbraid", name = "Ormer Ironbraid", note = "rettete ihm das Leben" },
		{ id = "archaeologist-flagongut", name = "Archäologe Flagongut", note = "will sein Fossil" },
	},
})

Translate("deDE", "longbraid-the-grim", {
	title = "Longbraid der Grimmige",
	subtitle = "Befehlshaber des Regiments von Dun Modr",
	found = "Das Lager vor Dun Modr",
	hint = [=[Sucht den zwergischen Befehlshaber auf, der das Lager vor dem gefallenen Dun Modr hält.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Longbraid" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Longbraid der Grimmige führte das Regiment aus {link:ironforge}Ironforge{/link}, das {link:dun-modr}Dun Modr{/link} und den {link:thandol-span}Thandol-Übergang{/link} bewachte. Er verlor beides. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} sprengten in einem Hinterhalt die westliche Brücke, und sein Bruder starb mit ihr. Bevor sich das Regiment erholen konnte, fielen sie über die Stadt her. Longbraid blies das Horn zum Rückzug, und nun hält er mit den wenigen, die überlebten, ein kleines Lager vor den Mauern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Longbraid ist der Kummer und die Sturheit von Khaz Modan in einem einzigen {link:dwarves}Zwerg{/link}. Er hat keine Reserve, keine Verbündeten, die er entbehren könnte, und keine Stadt, und doch hat er die Straße nach Norden nicht verlassen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er blies zum Rückzug, als {link:dun-modr}Dun Modr{/link} fiel, und rettete, was von seinem Regiment übrig war.
• Er schickte einen Reiter mit dem verwundeten {link:harlo-barnaby}Harlo Barnaby{/link} nach Süden nach Menethil.
• Er jagt den Hexenmeister, der die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} im {link:wetlands}Sumpfland{/link} anführt.
• Er schickte einen Späher, den alten Rustlocke, zur östlichen Brücke, und der Späher kehrte nie zurück.]=],
		},
	},
	chapters = {
		{
			title = "Der Fall von Dun Modr",
			hint = "Bringt Nachricht von dem verwundeten Soldaten in Menethil.",
			text = [=[Longbraid hörte, dass der junge {link:harlo-barnaby}Harlo{/link} überlebt hatte, und einen Augenblick lang gab ihm die Nachricht Hoffnung. Dann erzählte er den Rest ohne Umschweife. {link:dun-modr}Dun Modr{/link} war verloren. Das Regiment, das es gehalten hatte, war nur noch ein Schatten seiner selbst.]=],
		},
		{
			title = "Eine grimmige Aufgabe",
			hint = [=[Spürt den Hexenmeister auf, der die Dunkeleisenzwerge anführt.]=],
			text = [=[Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} des Sumpflands wurden von {link:balgaras-the-foul}Balgaras{/link} dem Fauligen angeführt, einem Hexenmeister, der andere in den Tod schickte und sich selbst außer Reichweite hielt. Als sein Ohr vor Longbraid gelegt wurde, empfand der Befehlshaber keine Freude daran. Die Toten würden nicht zurückkommen. Doch die Lebenden könnten schlafen, und der Rest der Dunkeleisenzwerge müsste vertrieben werden, bevor ein neuer Herr käme.]=],
		},
	},
	mentions = {
		{ text = "Der Fall von {link:dun-modr}Dun Modr{/link}" },
		{ text = "Eine grimmige Aufgabe" },
		{ text = "Die Wut sitzt tief, sein Bruder gerächt" },
		{ text = "Auf der Suche nach der Ausgrabungsmannschaft" },
	},
	bonds = {
		{ id = "motley-garmason", name = "Motley Garmason", note = "durch Ehre verpflichtet, an seiner Seite zu bleiben" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "sein Offizier" },
		{ id = "harlo-barnaby", name = "Harlo Barnaby", note = "ein Soldat, den er in Sicherheit schickte" },
		{ id = "balgaras-the-foul", name = "Balgaras der Faulige", note = "Feind" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "plante den Tod seines Bruders" },
	},
})

