	found = "Das Lager vor Dun Modr",
	hint = "Findet den Sprengstoffexperten in Longbraids Lager.",
	allegiance = "Königreich Ironforge",
	aliases = { "Ashlan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ashlan Stonesmirk wurde wegen seines Wissens über Sprengpulver zum Regiment von {link:dun-modr}Dun Modr{/link} versetzt. Als nahe dem Stonewroughtdamm in {link:loch-modan}Loch Modan{/link} ein seltsames Pulver gefunden wurde, schickte man es ihm. Er erkannte es sofort an seinen silbernen Kristallen und seinem Geruch: Seaforium. Trocken ist es harmlos. Nass könnte es {link:ironforge}Ironforge{/link} selbst aus dem Berg sprengen. Er wusste auch, wie man es unschädlich macht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er benannte das Pulver der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} und gab das Rezept, um es zu entschärfen.]=],
		},
	},
	mentions = {
		{ text = "Eine dunkle Bedrohung zieht herauf" },
		{ text = "Eine dunkle Bedrohung zieht herauf" },
	},
	bonds = {
		{ id = "chief-engineer-hinderweir-vii", name = "Chefingenieur Hinderweir VII.", note = "schickte ihm das Pulver" },
	},
})

Translate("deDE", "harlo-barnaby", {
