Translate("deDE", "rethiel-the-greenwarden", {
	title = "Rethiel der Grünwächter",
	subtitle = "Geist des Sumpfes",
	found = "Der Sumpf östlich der Abzweigung nach Dun Modr",
	hint = [=[Sucht den Geist des Sumpfes zwischen den Krokilisken östlich der Straße nach Dun Modr.]=],
	allegiance = "Das Sumpfland",
	aliases = { "Der Grünwächter", "Rethiel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Grünwächter ist ein Geist des lebendigen Sumpfes. Seeleute in Menethil sprechen von ihm als einem Untier, das Männer in zwei Hälften beißt. Die Wahrheit ist seltsamer. Er hat viele Namen und hört auf wenige, doch wem er vertraut, der darf ihn Rethiel nennen. Er fühlt das {link:wetlands}Sumpfland{/link} als seinen eigenen Leib. Er sagt, das Land weine aus eiternden Wunden, und die Völker der Welt hätten sein Vertrauen schon früher auf die Probe gestellt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verlangt, dass die Zahl der Moosfell-{link:gnolls}Gnolle{/link} verringert wird, denn sie sind dem Land entwachsen.
• Er zerschmettert die Feuersteine der Gnolle und wirft sie ins Meer.
• Er strebt danach, die fiebrigen Moorkriecher in den Sumpf zurückzulegen.]=],
		},
	},
	mentions = {
		{ text = "Der Grünwächter" },
		{ text = "Trampelnde Pfoten" },
		{ text = "Feuertabu" },
		{ text = "Blasen auf dem Land" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Erster Maat Fitzsimmons", note = "warnt Suchende vor ihm" },
	},
})

Translate("deDE", "howin-kindfeather", {
	title = "Howin Kindfeather",
	subtitle = "Greifenreiter des Sumpflands",
	found = [=[Ein Lager abseits der Straße östlich von Whelgars Ausgrabungsstätte]=],
	hint = [=[Findet den Zwerg und seinen Greifen, die abseits der Straße östlich von Whelgars Grabung lagern.]=],
	allegiance = "Wildhammerklan",
	aliases = { "Howin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Howin Kindfeather lagert mit seinem Greifen Bassbeak abseits der Straße durch das {link:wetlands}Sumpfland{/link}. Einst schickte er den Vogel mit einem Brief nach Menethil, um Welpenschuppen zu bestellen, worüber der Gerber des Hafens noch heute staunt. Er spuckt aus, wenn er von den Dunkeleisenzwergen, den {link:dragonmaw-clan}Dragonmaw{/link} und den Drachen spricht, die sie ritten, und er kann sich nicht entscheiden, wen er am meisten hasst. Er will die Dinge richtigstellen. Sein Plan braucht einen Umhang gegen Drachenfeuer, Zähne, um ihn zu nähen, und einen Greifen mit vollem Bauch.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kauft die Schuppen der purpurnen Welpen, die vor Drachenfeuer schützen.
• Er sammelt Klingenmaulzähne und Klingenmauleier für seinen Plan.]=],
		},
	},
	mentions = {
		{ text = "Lieferung einer purpurnen Kiste" },
		{ text = "Klingenmaul-Nadelstiche" },
		{ text = "Harte Zeiten" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "verkaufte ihm die Schuppen" },
	},
})

Translate("deDE", "hervdana-saegrund", {
	title = "Hervdana Saegrund",
	subtitle = "Schamanin der südlichen Fälle",
	found = "Eine Höhle unter den südlichen Fällen",
