Translate("deDE", "chieftain-nek-rosh", {
	title = "Häuptling Nek'rosh",
	subtitle = "Häuptling der Dragonmaw",
	found = "Angerfang-Lager",
	hint = [=[Stellt Euch dem Häuptling, der die Dragonmaw von ihrem Lager in den östlichen Hügeln aus anführt.]=],
	allegiance = "Dragonmawklan",
	aliases = { "Nek'rosh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nek'rosh ist der Häuptling des {link:dragonmaw-clan}Dragonmawklans{/link} im {link:wetlands}Sumpfland{/link}. Er ist der Sohn von Nekros, der den Klan in den Jahren anführte, als dieser die roten Drachen gefangen hielt. Nekros zwang die Drachen mit mächtiger Magie unter seinen Willen. Als die Magie versagte, wandten sich die Drachen gegen ihre Herren, und Nekros wurde getötet. Sein Sohn hat Rache an den Drachen geschworen, die ihn erschlugen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Unter Nek'rosh ist aus einem zerschlagenen Klan wieder ein Heer geworden. Die {link:dragonmaw-clan}Dragonmaw{/link} sind nach {link:dun-algaz}Dun Algaz{/link} vorgedrungen, haben Belagerungsmaschinen gebaut und ihren Blick auf den Hafen von Menethil gerichtet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelte die verstreuten {link:dragonmaw-clan}Dragonmaw{/link} im {link:angerfang-encampment}Angerfang-Lager{/link}.
• Er trieb seine Krieger nach {link:dun-algaz}Dun Algaz{/link} und schnitt die Straße zwischen Menethil und {link:loch-modan}Loch Modan{/link} ab.
• Er baute Katapulte, um den Hafen von Menethil zu belagern.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Die Chroniken des Zweiten Krieges erzählen von den {link:dragonmaw-clan}Dragonmaw{/link}, die die Drachenkönigin in {link:grim-batol}Grim Batol{/link} gefangen hielten. Welche Rolle Nek'rosh selbst in jenen Jahren spielte, sagen sie nicht.]=],
		},
	},
	chapters = {
		{
			title = "Der Sohn von Nekros",
			hint = [=[Bringt die Kriegsbanner der Dragonmaw zum Hauptmann in der Burg Menethil.]=],
			text = [=[Als die Banner vor ihn gelegt wurden, erzählte {link:captain-stoutfist}Hauptmann Stoutfist{/link}, was die {link:dwarves}Zwerge{/link} über ihren Feind wussten. Die {link:dragonmaw-clan}Dragonmaw{/link} waren nicht mehr, was sie gewesen waren, als sie Drachen ritten. Ihr Häuptling war der Sohn des {link:orcs}Orcs{/link}, der einst den roten Schwarm versklavt hatte, und er hatte nicht vergessen, wie sein Vater starb.]=],
		},
		{
			title = "Besiegt Nek'rosh",
			hint = "Verbrennt die Katapulte und streckt den Häuptling nieder.",
			text = [=[Zuerst brannten die Katapulte, und Menethil war vor ihnen sicher. Dann fiel Nek'rosh in seinem eigenen Lager. {link:captain-stoutfist}Stoutfist{/link} hielt es für einen schweren Schlag, von dem sich der Klan vielleicht nie erholen würde.]=],
		},
	},
	mentions = {
		{ text = "Kriegsbanner" },
		{ text = "Nek'roshs Gambit" },
		{ text = "Besiegt Nek'rosh" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Hauptmann Stoutfist", note = "Feind" },
		{ id = "ma-ruk-wyrmscale", name = "Ma'ruk Wyrmscale", note = "sein Kriegsherr in Dun Algaz" },
		{ id = "alexstrasza", name = "Alexstrasza", note = "Königin der Drachen, die sein Vater versklavte" },
	},
})

Translate("deDE", "ma-ruk-wyrmscale", {
	title = "Ma'ruk Wyrmscale",
	subtitle = "Kriegsherr der Dragonmaw",
	found = "Dun Algaz",
	hint = [=[Stellt Euch dem Kriegsherrn der Dragonmaw, der den Pass von Dun Algaz hält.]=],
	allegiance = "Dragonmawklan",
	aliases = { "Ma'ruk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ma'ruk Wyrmscale ist ein Kriegsherr des {link:dragonmaw-clan}Dragonmawklans{/link}. Er führt die {link:orcs}Orcs{/link} an, die in den Pass von {link:dun-algaz}Dun Algaz{/link} herabgekommen sind, wo sie jedem Reisenden zwischen {link:loch-modan}Loch Modan{/link} und dem {link:wetlands}Sumpfland{/link} auflauern. Solange er den Pass hält, erreicht keine Verstärkung den Hafen von Menethil über Land.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ma'ruk ist die Schneide von Nek'roshs Klinge. Die Belagerung Menethils durch den Häuptling hängt davon ab, dass er den Pass hält.]=],
		},
	},
	bonds = {
		{ id = "chieftain-nek-rosh", name = "Häuptling Nek'rosh", note = "sein Häuptling" },
	},
})

Translate("deDE", "dragonmaw-clan", {
	title = "Dragonmawklan",
	aliases = { "Dragonmaw", "Orcs der Dragonmaw" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dragonmaw sind ein Klan von {link:orcs}Orcs{/link} der alten {link:horde}Horde{/link}. Im {link:second-war}Zweiten Krieg{/link} taten sie, was kein anderer Klan vermochte: Sie machten die roten Drachen zu ihren Dienern. Von ihrer Festung in {link:grim-batol}Grim Batol{/link} aus hielten sie {link:alexstrasza}Alexstrasza{/link}, die Drachenkönigin, durch die Macht eines Artefakts gefangen, das {link:deathwing}Todesschwinge{/link} geschmiedet hatte, und zogen ihre Jungen als Kriegsreittiere auf. Rote Drachen, geritten von Orcs der Dragonmaw, verbrannten die Schiffe der {link:alliance}Allianz{/link} auf See.]=],
		},
		{
			title = "Der Fall",
			text = [=[Die Magie, die die Drachen band, versagte. Der rote Schwarm wandte sich gegen den Klan und jagte ihn ohne Gnade. Nekros, der die Dragonmaw angeführt hatte, wurde erschlagen, und der Klan wurde fast vernichtet. Die wenigen Überlebenden flohen aus {link:grim-batol}Grim Batol{/link} und versteckten sich in den Bergen östlich der Straße durch das {link:wetlands}Sumpfland{/link}.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die Dragonmaw sind unter {link:chieftain-nek-rosh}Häuptling Nek'rosh{/link}, dem Sohn von Nekros, wieder stark geworden. Vom {link:angerfang-encampment}Angerfang-Lager{/link} und dem verborgenen {link:dragonmaw-retreat}Dragonmaw Retreat{/link} aus schlagen sie nach Westen zu, und sie haben den Pass von {link:dun-algaz}Dun Algaz{/link} eingenommen. Sie bauen Katapulte, sammeln Waffen und träumen, so flüstert man, noch immer von Drachen. Die {link:dwarves}Zwerge{/link} von Menethil nennen sie wild, doch sie wissen, dass der Klan ohne seine Drachen eine geringere Bedrohung ist als der Klan, der einst den Himmel verdunkelte.]=],
		},
	},
})

Translate("deDE", "third-fleet", {
	title = "Dritte Flotte",
	aliases = { "Die Dritte Flotte", "die Verdammte Flotte" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dritte Flotte von {link:kul-tiras}Kul Tiras{/link} segelte im {link:second-war}Zweiten Krieg{/link}, dem letzten großen Krieg gegen die {link:horde}Horde{/link}. Ihre Schiffe kamen von den Küsten Lordaerons, und mindestens ein Schiff, das nicht zu ihr gehörte, schloss sich ihr zum Schutz an: die {i}Flying Osprey{/i}, die eine Ladung lichtgeschmiedeten Eisens trug. Vor der Küste des Sumpflands fielen {link:orcs}Orcs{/link} auf roten Drachen über die Flotte her. Die Schiffe brannten und sanken, und die Wracks liegen noch an der Nordwestküste, wo der Ort die verlorene Flotte heißt.]=],
		},
		{
			title = "Der Fluch",
			text = [=[An Bord der {i}Intrepid{/i} war etwas versteckt: ein verfluchtes Auge von Paleth, eingeschlossen in der Schiffstruhe des Kapitäns. Die Augen wurden von menschlichen Priestern geschaffen, um in heiligem Licht zu leuchten, doch dieses hatte zu viel Kummer mitangesehen. Seine Macht hält die ertrunkenen Mannschaften in ihren verrottenden Rümpfen fest. Nur ein Mann der Flotte lebt noch, der Erste Maat {link:first-mate-fitzsimmons}Fitzsimmons{/link}, und er trinkt in Menethil, damit er nicht von ihnen träumt.]=],
		},
		{
			title = "Die Ladung",
			text = [=[Die {link:murlocs}Murlocs{/link} der Küste haben die {i}Flying Osprey{/i} ausgeplündert. Ihre lichtgeschmiedeten Barren sind bei jenen begehrt, die gegen die Untoten kämpfen. Eine Nachtelfe von {link:teldrassil}Teldrassil{/link}, {link:sylessa-duskwhisper}Sylessa Duskwhisper{/link}, sagt, das Schiff habe auch Nord'el getragen, eine Blume vom Hyjal.]=],
		},
	},
})

Translate("deDE", "goaz-stone", {
	title = "Goaz-Stein",
	aliases = { "Der Goaz-Stein" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Goaz-Stein ist eine große Tafel, die {link:prospector-whelgar}Prospektor Whelgar{/link} bei seiner Grabung im {link:wetlands}Sumpfland{/link} ausgrub, kurz bevor die Raptoren sie überrannten. Sie ist in der Schrift der Titanen gemeißelt. Als sie gefunden wurde, war sie an vier Stellen zerbrochen, und die verlorenen Stücke trugen die Namen Ados, Modr, Golm und Neru. Selbst unvollständig sprach die Tafel von einem göttlichen Plan und einer unheilvollen Prophezeiung.]=],
		},
		{
			title = "Die Lesung",
			text = [=[Als die vier Bruchstücke wiederhergestellt waren, begann {link:prospector-whelgar}Whelgar{/link} das langsame Werk der Übersetzung. Die ersten neuen Worte, die er las, erzählten von Alten Göttern, angekettet unter dem Land. Die {link:explorers-league}Forscherliga{/link} hat schon früher Titanenschnitzereien gefunden, doch selten solche, die so deutlich von dem sprechen, was darunter liegt.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:prospector-whelgar}Whelgar{/link} hat seine Lesung nicht beendet. Über seiner Grabung, in den Hügeln, hat Nebel begonnen, von den Bergen herabzusinken, und Konstrukte der Titanen wandeln wieder. Ob der Stein und das Erwachen des Hochlands miteinander verbunden sind, weiß die Liga noch nicht.]=],
		},
	},
})
